// Light passing through the 1st layer of water electrons. 
// Electrons create a new wave (same wavelength, same velocity, different phase) which 
// combined with the original wave results in a phase shift.
// Add more layers of electrons and light move slower in water due to secondary waves
// accumulating phase shifts as the light goes through "layers of water electrons".

#define PI 3.14159265358979323846

float wave(vec2 p, vec2 n, float t, float spacialFreq, float phase, float v)
{
    return cos (phase+2.0*PI*spacialFreq*(dot(p,n)-t*v));
}

vec4 RED = vec4(1.0, 0.0, 0.0, 1.0);
vec4 GREEN = vec4(0.0, 1.0, 0.0, 1.0);
vec4 BLUE = vec4(0.0, 0.0, 1.0, 1.0);
vec4 WHITE = vec4(1.0, 1.0, 1.0, 1.0);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float wavelength = 0.5;
    float spacialFreq = 1.0 / wavelength;
    float velocity = 0.2;

    float originalAmplitude = 1.0;
    float original = wave(uv, vec2(1.0, 0.0), iTime, spacialFreq, 0.0, velocity);
    float secondaryAmplitude = 0.2;
    float secondaryPhase = 0.5;
    if (iMouse.z > 0.5)
    {
        secondaryAmplitude = iMouse.y / iResolution.y;
        secondaryPhase = iMouse.x / iResolution.x * PI;
    }
    float secondary = wave(uv, vec2(1.0, 0.0), iTime, spacialFreq, secondaryPhase * PI, velocity) * secondaryAmplitude;
    float sum = original + secondary;

    // Output to screen
    float o = abs(0.5+original*0.3-uv.y);
    fragColor = GREEN * smoothstep(0.01, 0.0, o);

    float s = abs(0.5+secondary*0.3-uv.y);
    fragColor += BLUE*smoothstep(0.01, 0.0, s);

    s = abs(0.5+sum*0.3-uv.y);
    fragColor += vec4(smoothstep(0.01, 0.0, s));
}
